package com.mentality.forgewebmap.storage;import java.nio.file.Path;final class TileRootResolver{static Path resolve(Path server,Path world,boolean inside,String dir){Path base=(inside?world:server).toAbsolutePath().normalize();Path result=base.resolve(dir).normalize();if(!result.startsWith(base))throw new IllegalArgumentException("tilesDirectory escapes its storage root");return result;}}
